package net.civeira.phylax.features.access.clientidentity.application.policy;

import jakarta.enterprise.event.Observes;
import net.civeira.phylax.common.security.Actor;
import net.civeira.phylax.features.access.clientidentity.application.visibility.ClientIdentityVisibilityCheck;

public class TenantAccesible {

  /**
   * Constant for platform field
   *
   * @autogenerated VisibilityPolicyGenerator
   */
  private static final String ROL_PLATFORM = "platform:*";

  /**
   * @autogenerated VisibilityPolicyGenerator
   * @param filter
   */
  public void filterVisibles(@Observes ClientIdentityVisibilityCheck filter) {
    Actor actor = filter.getInteraction().getActor();
    if (!actor.hasRole(ROL_PLATFORM)) {
      filter.peek(fl -> fl.setUserTenantTenantAccesible(actor.getTenant().orElse(null)));
    }
  }
}
